CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS providers (id TEXT PRIMARY KEY, name TEXT NOT NULL, capabilities JSONB NOT NULL DEFAULT '{}', priority INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS titles (id TEXT PRIMARY KEY, canonical_title TEXT NOT NULL, original_title TEXT, description TEXT, release_date DATE, year INTEGER, status TEXT NOT NULL DEFAULT 'active', media_type TEXT NOT NULL, runtime INTEGER, original_language TEXT, country TEXT, rating NUMERIC(4,2), rating_count INTEGER NOT NULL DEFAULT 0, popularity_score NUMERIC(12,4) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS titles_canonical_title_idx ON titles (canonical_title); CREATE INDEX IF NOT EXISTS titles_updated_at_idx ON titles (updated_at);
CREATE TABLE IF NOT EXISTS title_aliases (id BIGSERIAL PRIMARY KEY, title_id TEXT NOT NULL REFERENCES titles(id) ON DELETE CASCADE, language TEXT NOT NULL, type TEXT NOT NULL, value TEXT NOT NULL, normalized_value TEXT NOT NULL, UNIQUE(title_id, language, type, normalized_value)); CREATE INDEX IF NOT EXISTS title_aliases_normalized_idx ON title_aliases(normalized_value);
CREATE TABLE IF NOT EXISTS genres (id BIGSERIAL PRIMARY KEY, name TEXT UNIQUE NOT NULL); CREATE TABLE IF NOT EXISTS title_genres (title_id TEXT REFERENCES titles(id) ON DELETE CASCADE, genre_id BIGINT REFERENCES genres(id) ON DELETE CASCADE, PRIMARY KEY(title_id,genre_id));
CREATE TABLE IF NOT EXISTS tags (id BIGSERIAL PRIMARY KEY, name TEXT UNIQUE NOT NULL); CREATE TABLE IF NOT EXISTS title_tags (title_id TEXT REFERENCES titles(id) ON DELETE CASCADE, tag_id BIGINT REFERENCES tags(id) ON DELETE CASCADE, PRIMARY KEY(title_id,tag_id));
CREATE TABLE IF NOT EXISTS people (id TEXT PRIMARY KEY, name TEXT NOT NULL, metadata JSONB NOT NULL DEFAULT '{}'); CREATE TABLE IF NOT EXISTS credits (id BIGSERIAL PRIMARY KEY, title_id TEXT REFERENCES titles(id) ON DELETE CASCADE, person_id TEXT REFERENCES people(id) ON DELETE CASCADE, role TEXT NOT NULL, character_name TEXT, UNIQUE(title_id,person_id,role,character_name));
CREATE TABLE IF NOT EXISTS artworks (id TEXT PRIMARY KEY, title_id TEXT REFERENCES titles(id) ON DELETE CASCADE, provider_id TEXT REFERENCES providers(id), external_id TEXT, url TEXT NOT NULL, type TEXT NOT NULL, width INTEGER, height INTEGER, language TEXT, license_status TEXT NOT NULL DEFAULT 'unknown');
CREATE TABLE IF NOT EXISTS seasons (id TEXT PRIMARY KEY, title_id TEXT REFERENCES titles(id) ON DELETE CASCADE, season_number INTEGER NOT NULL, name TEXT, overview TEXT, release_date DATE, episode_count INTEGER, UNIQUE(title_id,season_number));
CREATE TABLE IF NOT EXISTS episodes (id TEXT PRIMARY KEY, title_id TEXT REFERENCES titles(id) ON DELETE CASCADE, season_id TEXT REFERENCES seasons(id) ON DELETE SET NULL, episode_number INTEGER, absolute_number INTEGER, title TEXT NOT NULL, overview TEXT, air_date DATE, runtime INTEGER, media_type TEXT NOT NULL, UNIQUE(title_id,season_id,episode_number));
CREATE TABLE IF NOT EXISTS provider_items (id BIGSERIAL PRIMARY KEY, provider_id TEXT REFERENCES providers(id) ON DELETE CASCADE, external_id TEXT NOT NULL, title_id TEXT REFERENCES titles(id) ON DELETE SET NULL, payload JSONB NOT NULL DEFAULT '{}', fetched_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(provider_id,external_id));
CREATE TABLE IF NOT EXISTS provider_episode_mappings (provider_id TEXT REFERENCES providers(id) ON DELETE CASCADE, external_id TEXT NOT NULL, episode_id TEXT REFERENCES episodes(id) ON DELETE CASCADE, provider_season_number INTEGER, provider_episode_number INTEGER, PRIMARY KEY(provider_id,external_id));
CREATE TABLE IF NOT EXISTS releases (id TEXT PRIMARY KEY, title_id TEXT REFERENCES titles(id) ON DELETE CASCADE, episode_id TEXT REFERENCES episodes(id) ON DELETE CASCADE, resolution TEXT, quality INTEGER NOT NULL DEFAULT 0, codec TEXT, container TEXT, stream_type TEXT NOT NULL, region TEXT, language TEXT);
CREATE TABLE IF NOT EXISTS audio_tracks (id BIGSERIAL PRIMARY KEY, release_id TEXT REFERENCES releases(id) ON DELETE CASCADE, language TEXT NOT NULL); CREATE TABLE IF NOT EXISTS subtitle_tracks (id BIGSERIAL PRIMARY KEY, release_id TEXT REFERENCES releases(id) ON DELETE CASCADE, language TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS playback_sources (id TEXT PRIMARY KEY, provider_id TEXT REFERENCES providers(id) ON DELETE CASCADE, source_id TEXT NOT NULL, title_id TEXT REFERENCES titles(id) ON DELETE CASCADE, episode_id TEXT REFERENCES episodes(id) ON DELETE CASCADE, release_id TEXT REFERENCES releases(id) ON DELETE CASCADE, stream_type TEXT NOT NULL, format TEXT NOT NULL, resolution TEXT, quality INTEGER NOT NULL DEFAULT 0, audio_languages TEXT[] NOT NULL DEFAULT '{}', subtitle_languages TEXT[] NOT NULL DEFAULT '{}', region TEXT, license_status TEXT NOT NULL, availability_status TEXT NOT NULL DEFAULT 'unknown', priority INTEGER NOT NULL, health_score INTEGER NOT NULL DEFAULT 0, latency INTEGER NOT NULL DEFAULT 0, last_checked_at TIMESTAMPTZ, expires_at TIMESTAMPTZ, UNIQUE(provider_id,source_id)); CREATE INDEX IF NOT EXISTS playback_sources_lookup_idx ON playback_sources(title_id,episode_id,availability_status);
CREATE TABLE IF NOT EXISTS source_health (source_id TEXT PRIMARY KEY REFERENCES playback_sources(id) ON DELETE CASCADE, status TEXT NOT NULL, http_status INTEGER, latency INTEGER, error_rate NUMERIC(6,4) NOT NULL DEFAULT 0, consecutive_failures INTEGER NOT NULL DEFAULT 0, successful_checks INTEGER NOT NULL DEFAULT 0, last_success_at TIMESTAMPTZ, last_failure_at TIMESTAMPTZ, health_score INTEGER NOT NULL DEFAULT 0, checked_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS field_provenance (id BIGSERIAL PRIMARY KEY, entity TEXT NOT NULL, entity_id TEXT NOT NULL, field TEXT NOT NULL, provider_id TEXT REFERENCES providers(id), source_id TEXT, value_hash TEXT NOT NULL, confidence NUMERIC(5,4) NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS field_provenance_entity_idx ON field_provenance(entity,entity_id);
CREATE TABLE IF NOT EXISTS title_relationships (title_id TEXT REFERENCES titles(id) ON DELETE CASCADE, related_title_id TEXT REFERENCES titles(id) ON DELETE CASCADE, relationship TEXT NOT NULL, PRIMARY KEY(title_id,related_title_id,relationship));
CREATE TABLE IF NOT EXISTS sync_state (provider_id TEXT PRIMARY KEY REFERENCES providers(id) ON DELETE CASCADE, cursor TEXT, etag TEXT, last_synced_at TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'idle'); CREATE TABLE IF NOT EXISTS search_index_state (title_id TEXT PRIMARY KEY REFERENCES titles(id) ON DELETE CASCADE, indexed_at TIMESTAMPTZ, version TEXT);
CREATE TABLE IF NOT EXISTS admin_overrides (id BIGSERIAL PRIMARY KEY, entity TEXT NOT NULL, entity_id TEXT NOT NULL, operation TEXT NOT NULL, payload JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, actor_id TEXT, action TEXT NOT NULL, entity TEXT, entity_id TEXT, metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, role TEXT NOT NULL DEFAULT 'user', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS watch_progress (user_id TEXT REFERENCES users(id) ON DELETE CASCADE, episode_id TEXT REFERENCES episodes(id) ON DELETE CASCADE, progress_seconds INTEGER NOT NULL DEFAULT 0, duration_seconds INTEGER NOT NULL DEFAULT 0, completed BOOLEAN NOT NULL DEFAULT false, last_watched_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(user_id,episode_id));
